SELECT user_record.id FROM spectra_core.sys_user AS user_record WHERE user_record.deleted IS NULL
AND user_record.status = #{status}
AND ( user_record.primary_department_id IN
#{departmentId}
AND EXISTS ( SELECT 1 FROM spectra_core.sys_department AS primary_department WHERE primary_department.id = user_record.primary_department_id AND primary_department.deleted IS NULL ) OR EXISTS ( SELECT 1 FROM spectra_core.sys_user_department_membership AS membership JOIN spectra_core.sys_department AS department ON department.id = membership.department_id AND department.deleted IS NULL WHERE membership.user_id = user_record.id AND membership.department_id IN
#{departmentId}
AND membership.deleted IS NULL ) ) ORDER BY user_record.id

SELECT user_id, department_id,
FROM spectra_core.sys_user_department_membership WHERE deleted IS NULL AND user_id IN
#{userId}
AND department_id IN
#{departmentId}
ORDER BY user_id, department_id FOR UPDATE

mapper.update:
UPDATE spectra_core.sys_user_department_membership SET deleted = CURRENT_TIMESTAMP, updated_at = CURRENT_TIMESTAMP, updated_by = #{operatorId}, version = version + 1 WHERE deleted IS NULL AND user_id IN
#{userId}
AND department_id IN
#{departmentId}
